000165 |     private static ExportSpec buildSpec(AuditType type, PensionBatchRunMode mode,
000166 |             boolean staffSpecified) {
000167 |         int base;
000168 |         if (mode == PensionBatchRunMode.DAILY) {
000169 |             base = staffSpecified ? 10 : 40;
000170 |         } else {
000171 |             base = staffSpecified ? 70 : 100;
000172 |         }
000173 |         int queryNumber = base + (type == AuditType.NEW ? 0
000174 |                 : type == AuditType.CHANGED ? 10 : 20);
000175 |         String number = queryNumber < 100 ? "0" + queryNumber : Integer.toString(queryNumber);
000176 |         String category = type.getDisplayName();
000177 |         String queryName = "Q" + number + "_Excel出力_年金予約_" + category
000178 |                 + "_データ明細リスト";
000179 |         String scope = staffSpecified ? "担当者別" : "全担当者";
000180 |         String period = mode == PensionBatchRunMode.DAILY ? "日次" : "月次";
000181 |         String fileName = "年金予約【" + category + "】データ明細リスト（"
000182 |                 + scope + period + "）.xlsx";
000183 |         return new ExportSpec(type, queryName, fileName, category + "分データ",
000184 |                 "年金予約【" + category + "】データ明細リスト");
000185 |     }
