000199 |     private static void sortAudits(List<PensionAuditRecord> audits) {
000200 |         Collections.sort(audits, new Comparator<PensionAuditRecord>() {
000201 |             public int compare(PensionAuditRecord left, PensionAuditRecord right) {
000202 |                 PensionReservation a = left.getReservation();
000203 |                 PensionReservation b = right.getReservation();
000204 |                 int branch = compareInteger(a.getBranchNo(), b.getBranchNo());
000205 |                 if (branch != 0) {
000206 |                     return branch;
000207 |                 }
000208 |                 int customer = compareInteger(a.getCustomerNo(), b.getCustomerNo());
000209 |                 return customer != 0 ? customer : Long.valueOf(left.getAuditId())
000210 |                         .compareTo(Long.valueOf(right.getAuditId()));
000211 |             }
000212 |         });
000213 |     }
000214 | 
000215 |     private static int compareInteger(Integer left, Integer right) {
000216 |         if (left == null) {
000217 |             return right == null ? 0 : -1;
000218 |         }
000219 |         return right == null ? 1 : left.compareTo(right);
000220 |     }
